xql_query:
// ============================================================
// Rule: BYT_User Add to Admin Group
// Vendor: BeyondTrust
// Objective:
// Detect activity associated with BYT_User Add to Admin Group.
// Severity: SEV_040_HIGH
// Category: CREDENTIAL_ACCESS
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0004 - Privilege Escalation
// Technique: T1098 - Account Manipulation
// Technique: T1098.007 - Account Manipulation: Additional Local or Domain Groups

// Fonte de dados: logs do BeyondTrust Password Safe
dataset = beyondtrust_passwordsafe_raw  

// Filtra apenas eventos que contenham o termo "Administrators" no log bruto
// e que sejam da categoria "Configure" com evento do tipo "Add"
| filter _raw_log contains "Administrators"  
       and category = "Configure"  
       and event_name = "Add"  

// Seleciona os campos mais relevantes para análise
| fields user,           // Usuário que executou a ação
         category,       // Categoria do evento (ex.: Configure)
         user_name,      // Nome do usuário associado
         event_name,     // Tipo de evento (ex.: Add)
         group_name,     // Nome do grupo envolvido
         _raw_log        // Log bruto para contexto completo
